using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using System.Windows.Forms;
using ShareMeRowell;

class SukunaSkillChecks {
    static void Require(bool value,string message){if(!value)throw new Exception(message);}
    static IEnumerable<Control> All(Control root){foreach(Control c in root.Controls){yield return c;foreach(var child in All(c))yield return child;}}
    static object Field(object value,string name){return value.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(value);}
    static void Select(Form form,int role){All(form).OfType<CharacterTile>().Single(c=>c.RoleIndex==role).PerformClick();Application.DoEvents();}
    static SoftButton Use(Form form){return All(form).OfType<SoftButton>().Single(c=>c.AccessibleName=="Use character skill");}
    static SoftButton Auto(Form form){return All(form).OfType<SoftButton>().Single(c=>c.AccessibleName=="Automatically use unlocked skills");}
    static void Show(Form form){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();Application.DoEvents();}
    static void Snapshot(Form form,string path){Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(path);}}
    static string Digest(Bitmap image){using(var buffer=new MemoryStream()){image.Save(buffer,ImageFormat.Png);using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(buffer.ToArray()));}}
    static Bitmap Render(CharacterSkillScene scene,HeroProfile profile,int time){var image=new Bitmap(286,286);using(var g=Graphics.FromImage(image))scene.Draw(g,new Rectangle(0,0,286,286),profile,time,true);return image;}
    static void Sample(CharacterSkillPreview skill,int position){((Timer)Field(skill,"clock")).Stop();var watch=(System.Diagnostics.Stopwatch)Field(skill,"time");var playback=(SkillPlayback)Field(skill,"playback");long now=watch.ElapsedMilliseconds;playback.Start(now,CharacterSkills.Duration(19));playback.Update(now,true);playback.Update(now+position,false);typeof(CharacterSkillPreview).GetMethod("Activity",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(skill,null);((Timer)Field(skill,"clock")).Stop();skill.Invalidate();}
    static void Seed(string folder,long xp){Directory.CreateDirectory(folder);using(var file=File.Create(Path.Combine(folder,"adventurer.receipts")))using(var sha=SHA256.Create()){
        var header=System.Text.Encoding.ASCII.GetBytes("SMXP001\n");file.Write(header,0,header.Length);int id=0;while(xp>0){int points=(int)Math.Min(50,xp);var data=new byte[44];Array.Copy(BitConverter.GetBytes(++id),data,4);Array.Copy(BitConverter.GetBytes(points*262144L),0,data,32,8);Array.Copy(BitConverter.GetBytes(points),0,data,40,4);file.Write(data,0,data.Length);var hash=sha.ComputeHash(data);file.Write(hash,0,hash.Length);xp-=points;}file.Flush(true);
    }}
    [STAThread] static int Main(string[] args){try{
        Application.EnableVisualStyles();string folder=Path.GetFullPath(args[0]);Directory.CreateDirectory(folder);var checks=new List<string>();
        Require(MadaraSequence.Duration==5200&&SukunaSequence.Duration==4800,"Skill speed did not change");var body=new HashSet<int>();var shrine=new HashSet<int>();var eye=new HashSet<int>();for(int time=0;time<=4800;time++){var m=SukunaSequence.At(time);Require(m.Body>=0&&m.Body<24&&m.Guardian>=-1&&m.Guardian<24&&m.Eye>=-1&&m.Eye<16,"Domain addressed a missing cel");Require(m.Aura>=0&&m.Aura<=1&&m.Closeup>=0&&m.Closeup<=1,"Domain opacity escaped its range");body.Add(m.Body);if(m.Guardian>=0)shrine.Add(m.Guardian);if(m.Eye>=0)eye.Add(m.Eye);}Require(body.Count==24&&shrine.Count==24&&eye.Count==16&&SukunaSequence.At(4800).Complete,"Not all64 domain frames were reachable or the skill failed to end");var clock=new SkillPlayback();clock.Start(0,SukunaSequence.Duration);clock.Update(0,true);clock.Update(4800,true);Require(clock.Position==4800&&!clock.Running,"Sukuna used Madara's duration");checks.Add("Sukuna reaches all64 cels and finishes at4.8seconds; Madara now finishes at5.2seconds");
        var names=typeof(CharacterSkillScene).Assembly.GetManifestResourceNames();Require(names.Length==47&&!names.Any(n=>n.Contains("source")||n.EndsWith(".gif")||n.Contains("preview")),"Authoring/review art entered the executable");foreach(string asset in new[]{"cast","shrine","eye"})using(var stream=typeof(CharacterSkillScene).Assembly.GetManifestResourceStream("ShareMeRowell.sukuna_"+asset+".png"))using(var image=new Bitmap(stream)){int size=image.Width/4,rows=asset=="eye"?4:6;Require(size>=256&&image.Height==rows*size,"A Sukuna production atlas was malformed");for(int cell=0;cell<rows*4;cell++){int visible=0,clear=0;for(int y=0;y<size;y+=4)for(int x=0;x<size;x+=4){int a=image.GetPixel(cell%4*size+x,cell/4*size+y).A;if(a>60)visible++;if(a<=12)clear++;}Require(visible>0&&clear>5,"A cel was empty or replaced by an opaque background: "+asset+cell);}}checks.Add("All three Sukuna atlases have visible transparent cels; the47-image production allowlist excludes source and review files");
        string frames=Path.Combine(folder,"frames");Directory.CreateDirectory(frames);using(var scene=new CharacterSkillScene(19)){
            var profile=new HeroProfile{Role=19};var varied=new HeroProfile{Role=19,Look=1,Hair=5,HairColour=5,Skin=4,Eyes=3,Shirt=3,Element=4};var hashes=new HashSet<string>();foreach(int time in new[]{0,800,1500,2400,3400,4400,4800})using(var image=Render(scene,profile,time)){hashes.Add(Digest(image));using(var other=Render(scene,varied,time))Require(Digest(image)==Digest(other),"Personal colours altered a fixed Sukuna skill");image.Save(Path.Combine(folder,"sukuna-"+time+".png"));}Require(hashes.Count==7,"Domain reused an unchanged image between phases");for(int time=0,index=0;time<=4800;time+=50,index++)using(var image=Render(scene,profile,time))image.Save(Path.Combine(frames,"frame-"+index.ToString("000")+".png"));var pixel=profile.Copy();pixel.PixelPreview=true;using(var image=Render(scene,pixel,3400))image.Save(Path.Combine(folder,"sukuna-pixel.png"));
        }checks.Add("Actual domain renderer shows distinct sign, face reveal, shrine, energy and recovery scenes while retaining fixed appearance");
        string state=Path.Combine(folder,"locked-profile");using(var store=new JourneyStore(state)){
            var p=store.Profile.Copy();p.Animations=true;p.MotionOverride=true;Require(store.SaveProfile(p),"Fixture profile could not save");using(var form=new AdventurerForm(store,()=>{})){
                Show(form);All(form).OfType<TextBox>().Single(c=>c.AccessibleName=="Search characters").Text="Sukuna";Select(form,19);var skill=All(form).OfType<CharacterSkillPreview>().Single();Require(!skill.Running,"Locked Sukuna automatically used his skill");int forms=Application.OpenForms.Count;Use(form).PerformClick();Require(skill.Running&&skill.Visible&&Application.OpenForms.Count==forms,"Domain did not play in the existing card");Require(store.Xp==0&&store.Profile.Role==0,"Manual Domain Expansion equipped or awarded XP");Sample(skill,3400);Snapshot(form,Path.Combine(folder,"sukuna-inline.png"));foreach(var size in new[]{form.Size,form.MinimumSize}){form.Size=size;Application.DoEvents();foreach(var control in new Control[]{skill,Use(form),Auto(form)}){var bounds=new Rectangle(form.PointToClient(control.PointToScreen(Point.Empty)),control.Size);Require(form.ClientRectangle.Contains(bounds),"Domain or controls were clipped at a supported size");}}Use(form).PerformClick();Require(!skill.Running&&((Control)Field(form,"hero")).Visible,"Stop did not restore idle");All(form).OfType<TextBox>().Single(c=>c.AccessibleName=="Search characters").Text="";Select(form,23);Use(form).PerformClick();Require(skill.Running,"Madara manual skill was lost");Select(form,19);Require(!skill.Running,"Changing from Madara left his scene running");Use(form).PerformClick();Require(skill.Running,"Sukuna did not restart after changing characters");form.Close();}
        }using(var store=new JourneyStore(state))Require(store.Xp==0&&store.Profile.Role==0,"Manual skills changed saved progress");checks.Add("Locked Sukuna manual activation stays in-card with stop, character switching, supported-size layout and no persisted equip/XP changes");
        string unlock=Path.Combine(folder,"unlock-profile");Seed(unlock,Adventure.Threshold(88)-1);using(var store=new JourneyStore(unlock)){
            Require(store.Level==87,"Sukuna unlock fixture is incorrect");var p=store.Profile.Copy();p.Animations=true;p.MotionOverride=true;store.SaveProfile(p);using(var form=new AdventurerForm(store,()=>{})){Show(form);Select(form,19);var skill=All(form).OfType<CharacterSkillPreview>().Single();Require(!skill.Running,"Locked fixture auto-started");Require(store.AwardVerified(new FileMeta{name="isolated-sukuna-unlock.bin",size=262144,sha256=new string('e',64)})==1,"Fixture award did not advance");form.RefreshProgress();Require(store.Level==88&&skill.Running&&store.Profile.Role==0,"Sukuna unlock did not activate once without equipping");Use(form).PerformClick();form.RefreshProgress();Require(!skill.Running,"Normal XP refresh replayed Domain Expansion");Select(form,0);Select(form,19);Require(skill.Running,"Unlocked Sukuna selection did not auto-use");Auto(form).PerformClick();Require(!skill.Running&&!store.Profile.AutoSkills,"Auto Off did not persist and stop");Use(form).PerformClick();Require(skill.Running,"Auto Off blocked manual domain use");form.Close();}
        }using(var store=new JourneyStore(unlock))Require(!store.Profile.AutoSkills&&store.Level==88&&store.Profile.Role==0,"Domain changed saved Auto or genuine fixture progression");checks.Add("The existing Level88 gate activates once on selected unlock and card selection; Auto Off retains manual use and persists");
        using(var skill=new CharacterSkillPreview()){Require(!skill.Start(new HeroProfile{Role=19,Animations=false,MotionOverride=true}),"Domain bypassed Animation Off");Require(!skill.Playing&&!skill.Running,"Rejected domain started a background timer");}Require(!CharacterSkills.CanAutoUse(new HeroProfile(),19,87)&&CharacterSkills.CanAutoUse(new HeroProfile(),19,88)&&!CharacterSkills.Has(8),"Domain unlock leaked to another character");checks.Add("Sukuna respects Off and his original unlock without enabling other characters or background playback");
        File.WriteAllText(Path.Combine(folder,"result.json"),Wire.Encode(new{passed=checks.Count,checks=checks,artifactDirectory=folder,authoredFrames=64,reviewFrames=97,durationMilliseconds=4800,fixtureTimesUsed=true,phoneUsed=false,ownerProgressUsed=false,liveFocusForced=false}));Console.WriteLine(string.Join(Environment.NewLine,checks));return 0;
    }catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
